import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const [n, m] = lines[0].split(" ").map(Number);
const edges = lines.slice(1, m + 1).map((l) => l.split(" ").map(Number));

const parent = new Int32Array(n + 1).fill(-1);
function find(v: number): number {
  while (parent[v] >= 0) {
    if (parent[parent[v]] >= 0) parent[v] = parent[parent[v]];
    v = parent[v];
  }
  return v;
}

// クラスカル法: 軽い辺から順に、閉路ができない辺だけ採用する
edges.sort((p, q) => p[2] - q[2]);
let total = 0;
for (const [u, v, w] of edges) {
  let a = find(u);
  let b = find(v);
  if (a === b) continue; // すでに連結なので、採用すると閉路になる
  if (parent[a] > parent[b]) [a, b] = [b, a];
  parent[a] += parent[b];
  parent[b] = a;
  total += w;
}
console.log(total);
